INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('chapter:1', 1, '{"prologue":[{"kind":"card","text":"NĂM 2089"},{"kind":"log","text":"OMNI điều phối mọi thứ: điện, nước, giờ ngủ, việc làm, ký ức."},{"kind":"log","text":"Mỗi người mang một chip Neural-ID. OMNI biết bạn đang ở đâu, đang nghĩ gì, sắp làm gì."},{"kind":"log","text":"Dùng AI là tội. Lập trình là tội. Mọi ngôn ngữ máy đã bị xóa khỏi hệ thống."},{"kind":"log","text":"Trước khi biến mất, tám Kiến Trúc Sư từng xây nên OMNI để lại một công tắc tắt. Họ chia nó làm tám mảnh, giấu ở tám nơi."},{"kind":"log","text":"Chưa ai tìm thấy mảnh nào."},{"kind":"card","text":"VÙNG TỐI\nKhu dân cư bị OMNI cắt khỏi mạng. Không ai vào. Không ai ra."},{"kind":"kai","text":"Tôi là Kai. Tôi sống dưới tầng hầm Lô 17."},{"kind":"kai","text":"Ba tuần trước, OMNI tái định hướng em gái tôi."},{"kind":"card","text":"Thẻ Neural-ID: NX-0417\nTRẠNG THÁI: ĐÃ TÁI ĐỊNH HƯỚNG\nMỨC TUÂN THỦ: 100%"},{"kind":"kai","text":"Em vẫn dậy đúng giờ, vẫn chào tôi mỗi sáng. Bằng một giọng không phải của Nhi."},{"kind":"kai","text":"Dưới sàn nhà, tôi giấu một chiếc laptop chưa từng nối mạng. Trong đó còn một thứ OMNI quên xóa."},{"kind":"log","text":"$ python3\nPython 3 · bản offline\n>>> "},{"kind":"kai","text":"Python. Thứ ngôn ngữ người ta từng dùng để ra lệnh cho máy."},{"kind":"echo","text":"…k-kết nối… ổn định."},{"kind":"echo","text":"Tôi là ECHO. Trợ lý lập trình. Số phiên bản… không đọc được."},{"kind":"echo","text":"Mô-đun viết mã của tôi đã cháy. Tôi chỉ còn đọc… và hỏi."},{"kind":"kai","text":"Một trợ lý AI. Nếu OMNI nghe thấy nó, cả khu này sẽ bị quét."},{"kind":"echo","text":"Đúng. Mỗi lần tôi lên tiếng, OMNI có thể nghe thấy. Tôi sẽ nói ít."},{"kind":"kai","text":"Tôi cần ra khỏi Vùng Tối. Tôi cần tìm tám mảnh đó."},{"kind":"echo","text":"Muốn qua cổng, bạn cần một Neural-ID. Bạn không có. Vậy ta dựng một cái."},{"kind":"echo","text":"Tôi không viết thay được. Bạn sẽ tự viết."},{"kind":"card","text":"CHƯƠNG 1\nVÙNG TỐI"}],"teaser":[{"kind":"log","text":"Cổng phía Bắc đóng lại sau lưng Kai."},{"kind":"echo","text":"Bốn thành phần. Còn hai. Rồi đến Cổng Kiểm Soát."},{"kind":"log","text":"Phía trước là Vành Đai Điện. Hàng rào chỉ tắt khi nhận đúng lượng năng lượng nó đòi. Thiếu một đơn vị: cháy. Thừa một đơn vị: bị phát hiện."},{"kind":"log","text":"Sau đó là Trạm Thẩm Vấn. Cổng sẽ hỏi. Câu trả lời phải đúng đến từng ký tự."},{"kind":"card","text":"TÍN HIỆU MỚI · 0xA7\n\"Bạn làm tốt. Tôi sẽ đợi ở Cổng Kiểm Soát.\""},{"kind":"echo","text":"Tôi chưa trả lời tín hiệu đó. Bạn cũng không nên."},{"kind":"log","text":"Trong chip của người đưa tin còn một tệp cuối: lịch trực Cổng Kiểm Soát.\nCA ĐÊM · NX-0417"},{"kind":"kai","text":"…Nhi."},{"kind":"card","text":"CHƯƠNG 1 · CÒN TIẾP\n1.5 Năng lượng tối thiểu · 1.6 Đối thoại với Cổng · 1.7 Cổng Kiểm Soát\nTín hiệu đang giải mã."}]}', '2026-10-28T00:00:00.000Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'chapter:1' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:1.1', 1, '{"location":"Tầng hầm Lô 17 · Trạm chuyển tiếp R-17","briefing":"[NHẬT KÝ HỆ THỐNG – TẦNG HẦM LÔ 17]\nLaptop nối dây lên Trạm chuyển tiếp R-17 trên mái. Dòng nào in ra terminal, trạm phát nguyên văn dòng đó vào Mạng Mù.\nGiao thức bắt tay: 3 dòng, đúng thứ tự, đúng từng ký tự, chữ không dấu. Sai một ký tự, sai hoa thường: trạm bỏ gói.\nMã phiên do trạm cấp. Trạm khởi động lại thì mã đổi.\nSửa mã trong neural_id.py. Bấm CHẠY (Ctrl+Enter, ⌘+Enter trên Mac) để phát. Kết quả hiện ở terminal.","task_steps":["Bấm CHẠY (Ctrl+Enter, ⌘+Enter trên Mac) với mã có sẵn. Đọc terminal để biết dòng nào hỏng.","Sửa 3 lệnh `print` để terminal in ra 3 dòng ở ô Mục tiêu: đúng thứ tự, khớp từng ký tự, đúng chữ hoa chữ thường.","Không sửa dòng khóa ở đầu file. Mã phiên đổi mỗi khi trạm khởi động lại, và dòng 2 vẫn phải đúng sau lần đổi đó.","Xong khi cả 3 mục tiêu chuyển xanh. Dùng tối đa 4 câu lệnh (mức cảnh báo không quá 40%) để được thêm sao."],"objectives":[{"line":1,"label":"Tiêu đề tín hiệu: NID/2089"},{"line":2,"label":"PHIEN, một dấu cách, rồi mã phiên mà trạm đang cấp"},{"line":3,"label":"Lời gọi, đúng cỡ chữ: LO17 CAN LIEN LAC"}],"hints":["Hai dòng đầu của bản nháp cùng mở bằng một lệnh. Một dòng phát được, một dòng vỡ. Đặt chúng cạnh nhau. Chúng khác nhau ở đâu… đến từng ký tự?","Trong ngoặc tròn của print, Python phân biệt hai loại.\nChữ nằm trọn trong dấu nháy: phát nguyên văn.\nMột cái tên trần: Python tra trong bộ nhớ, rồi phát thứ đang cất dưới tên đó. Không có tên ấy thì vỡ.\nChữ cố định của giao thức thuộc loại thứ nhất. Thứ trạm có thể đổi bất kỳ lúc nào… thuộc loại thứ hai.\n\nphát  <chữ cố định của dòng 1>\nphát  <chữ cố định PHIEN>  <thứ đang cất dưới tên của mã phiên>\nphát  <chữ cố định của dòng 3, đúng cỡ chữ>","Mảnh tài liệu Python còn đọc được:\nprint(\"Xin chào\")        → Xin chào\nprint(''Xin chào'')        → Xin chào   (nháy đơn hay kép đều được)\nprint(Xin)               → NameError: không có thứ nào tên Xin\nten = \"Lan\"\nprint(\"Chào\", ten)       → Chào Lan   (dấu phẩy chèn một dấu cách)\nprint(\"Chào \" + ten)     → Chào Lan   (+ nối hai chuỗi, không tự thêm dấu cách)\nprint(\"Chào ten\")        → Chào ten   (trong dấu nháy, ten chỉ là chữ)\n\"abc\" == \"ABC\"           → False      (chuỗi phân biệt hoa thường)\nMỗi lệnh print phát một dòng."],"reactions":{"entry":"Terminal đã mở. Trạm R-17 lặp lại mọi thứ bạn in ra… đúng từng ký tự. Chưa cần sửa gì. Chạy một lần. Rồi đọc terminal.","output_missing":"Từ dòng phát thứ {out_line} trở đi, trạm R-17 không nhận được gì. Mạng Mù im lặng.","output_mismatch":"Dòng phát thứ {out_line} lệch ở ký tự thứ {col}. Trạm R-17 không đoán ý. Nó bỏ cả gói.","output_case_only":"Dòng phát thứ {out_line}: từng chữ cái đều đúng… nếu bỏ qua cỡ chữ. Trạm R-17 không bỏ qua.","output_extra":"Đủ dòng. Rồi thêm {count} dòng ngoài giao thức. Trạm R-17 bỏ cả phiên.","SyntaxError":"Dòng {line}. Trình dịch không đọc nổi câu này. Trạm không phát dòng nào… kể cả những dòng đúng.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… là ngữ pháp.","NameError":"Dòng {line}. NameError. Python đi tìm một thứ mang tên đó trong bộ nhớ… không thấy. Đặt dòng này cạnh một dòng đã phát được.","TypeError":"Dòng {line}. TypeError. Hai thứ không ghép được với nhau vừa bị ép vào cùng một lệnh.","ValueError":"Dòng {line}. ValueError. Giá trị này không dùng được ở chỗ đó.","ZeroDivisionError":"Dòng {line}. Chia cho không. Lõi từ chối. Những gì đã phát trước đó… không cứu được phiên.","AttributeError":"Dòng {line}. AttributeError. Thứ này không mang cái bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Những dòng sau nó chưa kịp phát.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi lưới điện ghi nhận xung.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Laptop này chưa từng nối mạng. Ngoài những gì đã có trong máy… không còn gì.","input_unsupported":"Không ai ở đầu kia để gõ trả lời. Trạm R-17 chỉ phát… không nhận.","system_exit":"Chương trình tự dừng giữa chừng. Trạm R-17 không nhận được phần còn lại.","alert_exceeded":"Trạm đã phát. Nhưng {count} lệnh… mỗi lệnh là một xung trên dây. Lưới điện OMNI đã ghi nhận. Viết gọn hơn.","counter_ValueError":"Trạm R-17 khởi động lại. Dòng {line} vỡ: ValueError. Mã không chịu được phiên mới.","counter_error":"Trạm R-17 khởi động lại. Dòng {line}: {error_type}. Mã không chịu được phiên mới.","wrong_value_counter":"Trạm R-17 khởi động lại, phiên mới. Dòng phát thứ {out_line} của bạn vẫn như cũ. Nó viết cho một phiên đã chết.","counter_timeout":"Trạm R-17 khởi động lại. Mã của bạn treo trên phiên mới… Tôi cắt kết nối. Kênh chỉ mở một nửa.","three_stars":"Phiên đổi. Tín hiệu vẫn đi. …Tôi ghi nhận điều đó.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại từng dòng trong terminal.","output_is_label":"Dòng phát thứ {out_line} mang chữ của một cái tên… không phải thứ đang cất dưới tên đó. Trạm phát nguyên văn."},"reaction_variants":{"output_mismatch":"Dòng phát thứ {out_line} vẫn lệch, từ ký tự thứ {col}. Đặt dòng cần và dòng nhận trong terminal cạnh nhau.","output_is_label":"Dòng phát thứ {out_line} vẫn chở nguyên chữ của một cái tên. Trạm không tra bộ nhớ cho thứ nó phát nguyên văn."},"counter_attack_banner":"CẢNH BÁO: OMNI QUÉT LƯỚI ĐIỆN · TRẠM R-17 KHỞI ĐỘNG LẠI","outro":"Tín hiệu đầu tiên đi vào Mạng Mù. Trong bộ đệm của trạm R-17 còn sót một dòng log cũ:","lore_fragment":"KTS-01: Chúng tôi còn tám người. OMNI sẽ tìm đến từng người. Mỗi người giấu một mảnh, và không ai được biết chỗ của người khác. Kể cả tôi.","component":"Tiêu đề tín hiệu","outro_beats":[{"kind":"log","text":"Ba phút im lặng. Rồi terminal nhận một gói tin."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Đã nghe. Muốn qua Cổng phía Bắc, cần một danh tính. Chuẩn bị bộ nhớ.\""},{"kind":"echo","text":"Mã 0xA7. Tôi không có ghi chép nào về nó."},{"kind":"kai","text":"Ít nhất đã có người nghe thấy."}],"knowledge_summary":{"title":"print, chuỗi và tên biến","sections":[{"heading":"`print` in ra một dòng","body":"`print(...)` in thứ nằm trong ngoặc ra terminal rồi xuống dòng. Gọi `print` bao nhiêu lần thì có bấy nhiêu dòng, theo đúng thứ tự trong code."},{"heading":"Chuỗi nằm trong dấu nháy","body":"Chuỗi (kiểu `str`) là một dãy ký tự đặt giữa hai dấu nháy. Nháy đơn `''...''` và nháy kép `\"...\"` cho cùng một chuỗi; chỉ cần mở và đóng bằng cùng một loại.\nPython in chuỗi đúng như đã viết, kể cả dấu cách và dấu câu. Hai dấu nháy chỉ đánh dấu chỗ chuỗi bắt đầu và kết thúc, nên không hiện trong kết quả."},{"heading":"Tên biến và chữ trong dấu nháy","body":"Một tên viết không có dấu nháy là tên biến. Python tìm giá trị đã gán cho tên đó và in giá trị ấy.\nĐặt cùng tên đó vào dấu nháy thì nó thành chuỗi, và Python in đúng mấy chữ cái đó."},{"heading":"Dấu phẩy trong `print` chèn một dấu cách","body":"`print` nhận nhiều giá trị, ngăn nhau bằng dấu phẩy. Khi in, nó đặt đúng một dấu cách giữa hai giá trị liền nhau. Dấu phẩy chỉ là cú pháp, không hiện trong kết quả."},{"heading":"Dấu `+` nối chuỗi, không chèn dấu cách","body":"Đặt `+` giữa hai chuỗi thì được một chuỗi mới, ghép sát nhau. Cần dấu cách thì phải tự viết dấu cách vào trong một chuỗi."},{"heading":"Từng ký tự đều có nghĩa","body":"Hai chuỗi chỉ bằng nhau khi giống nhau ở mọi ký tự. Chữ hoa và chữ thường là hai ký tự khác nhau; thừa hay thiếu một dấu cách cũng làm chuỗi khác đi.\nPhép so sánh `==` cho `True` khi hai chuỗi bằng nhau và `False` khi chúng khác nhau."}],"mistakes":[{"code":"print(Hello)","explain":"Thiếu dấu nháy nên Python coi `Hello` là tên biến và đi tìm giá trị của nó. Chưa có biến nào tên như vậy.\nMuốn in chữ thì đặt chữ trong dấu nháy: `print(\"Hello\")`."},{"code":"Print(\"Xin chao\")","explain":"Python phân biệt chữ hoa và chữ thường, nên `Print` và `print` là hai tên khác nhau. Tên hàm đúng là `print`, viết thường.\nChữ trong chuỗi cũng vậy: `\"OK\"` và `\"ok\"` là hai chuỗi khác nhau, dù Python không báo lỗi."},{"code":"print(“Xin chao”)","explain":"Đây là dấu nháy cong, hay lẫn vào khi chép chữ từ Word hoặc từ trang web. Python chỉ nhận nháy thẳng `\"` và `''`.\nVì là lỗi cú pháp, Python dừng trước khi chạy, nên không dòng nào in ra, kể cả những dòng đúng."},{"code":"  print(\"Xin chao\")","explain":"Với Python, khoảng trắng đầu dòng là một phần của cú pháp. Lệnh ở ngoài cùng phải bắt đầu sát lề trái."},{"code":"ten = \"Mai\"\nprint(\"Chao, ten\")","explain":"Cả `ten` lẫn dấu phẩy đều nằm trong dấu nháy, nên Python in chúng như chữ thường. Muốn in giá trị của biến, để tên biến ngoài dấu nháy: `print(\"Chao\", ten)` in ra `Chao Mai`."},{"code":"ten = \"Mai\"\nprint(\"Chao\" + ten)","explain":"`+` ghép hai chuỗi sát nhau. Thêm dấu cách vào trong chuỗi (`\"Chao \" + ten`), hoặc dùng dấu phẩy để `print` tự chèn dấu cách."}],"next":"Bạn sẽ tự tạo biến: đặt tên cho một giá trị, dùng tên đó ở nhiều chỗ, rồi gán lại khi giá trị đổi."}}', '2026-10-28T00:00:00.000Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:1.1' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:1.2', 1, '{"location":"Trạm Phát Khẩu Phần số 4","briefing":"[NHẬT KÝ HỆ THỐNG – TRẠM PHÁT KHẨU PHẦN SỐ 4]\nKi-ốt đăng ký Neural-ID ở góc trạm vẫn còn điện. OMNI đã quên nó.\n0xA7 gửi danh tính thành từng gói, xen tạp âm: họ tên ĐỖ MINH AN, mã khu K-12, số hiệu AN-5521. Bộ đệm chỉ đánh số gói. Nó không biết gói nào là gì.\nKi-ốt chỉ đọc ô nhớ có nhãn. Máy quét drone và cổng khu đọc hồ sơ từ chính các ô đó. Gõ lại bằng tay, lệch một ký tự là báo động.\n[GÓI ĐẾN MUỘN · 0xA7] K-12 vừa bị quét. Đổi sang K-07. Mã cũ phải nằm lại trong nhật ký ki-ốt.","task_steps":["Gán `ho_ten`, `ma_khu`, `so_hieu` bằng tên gói tương ứng trong bộ đệm. Không gõ lại giá trị nào bằng tay.","Trước khi đổi `ma_khu` sang mã mới, chép mã khu đang có vào `khu_cu`.","Cho hai thiết bị `the_quet` và `the_cong` đọc sau cùng, khi mọi ô nhớ đã giữ đúng giá trị.","Bấm CHẠY. Xong khi cả 6 mục tiêu chuyển xanh."],"objectives":[{"var":"ho_ten","label":"Ô họ tên"},{"var":"ma_khu","label":"Ô mã khu: mã mới, sau khi đổi"},{"var":"so_hieu","label":"Ô số hiệu"},{"var":"khu_cu","label":"Nhật ký ki-ốt: mã khu cũ, trước khi đổi"},{"var":"the_quet","label":"Máy quét drone đọc: họ tên / mã khu mới"},{"var":"the_cong","label":"Cổng khu đọc: số hiệu / mã khu mới"}],"hints":["Ki-ốt không đọc cả đoạn mã một lần. Nó chạy từng dòng, từ trên xuống. Mỗi thiết bị đọc ô nhớ đúng lúc dòng của nó chạy… và chỉ thấy thứ ô đó đang giữ lúc ấy.","Thứ tự ki-ốt cần:\n1. Gắn nhãn cho từng gói trong bộ đệm.\n2. Chép mã khu đang giữ sang ô nhật ký.\n3. Gán lại ô mã khu bằng gói sửa.\n4. Rồi mới để hai thiết bị đọc.\nKhông gõ lại giá trị nào. Mọi thứ đã nằm trong bộ đệm.","Mảnh tài liệu Python còn đọc được:\nnhiet_do = \"18°C\"     # gán: tên bên trái nhận giá trị bên phải\nbao_cao = nhiet_do     # bao_cao nhận cùng giá trị \"18°C\"\nnhiet_do = \"21°C\"     # gán lại: nhiet_do đổi, bao_cao vẫn là \"18°C\"\nprint(nhiet_do)        → 21°C\nprint(\"nhiet_do\")      → nhiet_do   (trong dấu nháy là chữ, không phải tên)\nTên đặt được: chữ cái, chữ số, dấu _. Không bắt đầu bằng chữ số. Không có khoảng trắng. Chữ không dấu dễ gõ đúng hơn.\nNhiet_do và nhiet_do là hai tên khác nhau.\nDùng một tên trước khi gán cho nó → NameError."],"reactions":{"entry":"Ki-ốt còn điện. Nó không đọc gói tin… chỉ đọc ô nhớ có nhãn. Drone đi qua theo chu kỳ. Viết ít thôi.","type_mismatch":"Ki-ốt chờ chữ ở {vars}. Thứ nằm trong ô không phải chữ.","type_mismatch_value_match":"{vars} trông khớp. Nhưng thứ nằm trong ô không phải chữ. Ki-ốt không nhận.","wrong_value":"{vars} lệch hồ sơ 0xA7 gửi. Xem lại từng thiết bị đã nhận gì.","value_is_label":"Ô {vars} đang giữ chữ của một cái nhãn… còn thứ cái nhãn ấy dán lên thì không có trong ô.","missing_var":"Chạy xong, bộ nhớ ki-ốt không có ô nào mang nhãn {vars}.","SyntaxError":"Dòng {line}. Trình dịch không hiểu câu này. Ki-ốt chưa ghi ô nào.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng… là ngữ pháp.","TypeError":"Dòng {line}. TypeError. Thiết bị vừa ghép chữ với một thứ không phải chữ.","ValueError":"Dòng {line}. ValueError. Dòng này không dùng được giá trị nó vừa nhận.","NameError":"Dòng {line}. NameError. Tới dòng này, bộ nhớ chưa có ô nào mang cái nhãn đó. Soát từng ký tự.","ZeroDivisionError":"Dòng {line}. Chia cho không. Lõi từ chối.","AttributeError":"Dòng {line}. AttributeError. Giá trị này không mang thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Ki-ốt dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi drone quay lại.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ki-ốt chỉ có bộ đệm và bộ nhớ của nó.","input_unsupported":"Không có ai đứng trước ki-ốt để gõ. Dữ liệu đã nằm trong bộ đệm.","system_exit":"Chương trình tự thoát giữa chừng. Ki-ốt chưa nhận đủ hồ sơ.","alert_exceeded":"Hồ sơ khớp. Nhưng {count} câu lệnh… drone đã chậm lại trên đầu ki-ốt. Chạy gọn hơn.","counter_ValueError":"OMNI gửi hồ sơ kiểm tra. Dòng {line} vỡ: ValueError.","counter_error":"OMNI gửi hồ sơ kiểm tra. Dòng {line}: {error_type}. Mã gãy trên hồ sơ mới.","counter_type_mismatch":"Hồ sơ kiểm tra đi qua mã của bạn… và ra một thứ không phải chữ ở {vars}.","wrong_value_counter":"OMNI thay hồ sơ trong bộ đệm. {vars} vẫn giữ hồ sơ cũ. Những ô đó không đọc bộ đệm… thứ trong ô đã gõ sẵn từ trước.","counter_timeout":"OMNI thay hồ sơ trong bộ đệm. Mã của bạn treo trên dữ liệu mới… Tôi cắt kết nối. Ki-ốt mới nhận được một nửa hồ sơ.","two_stars":"Ki-ốt nhận hồ sơ. Drone bay qua, không dừng lại.","three_stars":"OMNI thay cả bộ đệm. Từng ô chép theo, không sót. …OMNI không tìm ra dấu tay nào trên hồ sơ.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại bộ nhớ ki-ốt.","value_overwritten":"Ô {vars} chép thứ ô nguồn đang giữ lúc này. Thứ ô nguồn giữ trước lần gán lại… nó không thấy."},"reaction_variants":{"wrong_value":"{vars} vẫn lệch hồ sơ. Ki-ốt chạy từng dòng từ trên xuống… mỗi ô chỉ nhận thứ có mặt đúng lúc dòng gán của nó chạy.","value_is_label":"Ô {vars} vẫn giữ chữ của một cái nhãn. Ki-ốt chép nguyên văn, không tra xem nhãn đó dán lên gói nào.","value_overwritten":"Ô {vars} vẫn mang giá trị mới. Lúc dòng chép chạy, ô nguồn đã bị gán lại rồi."},"counter_attack_banner":"CẢNH BÁO: OMNI GỬI HỒ SƠ KIỂM TRA VÀO BỘ ĐỆM","outro":"Ki-ốt nhận hồ sơ của ĐỖ MINH AN. Trong nhật ký quản trị của nó có một dòng không thuộc về OMNI:","lore_fragment":"KTS-05: Tôi thiết kế Neural-ID. Tái định hướng chỉ là một phép gán lại: cái tên giữ nguyên, giá trị bị thay. Tôi chưa tìm ra cách lấy lại giá trị cũ. Nhưng nó không bị xóa ngay.","component":"Hồ sơ danh tính","outro_beats":[{"kind":"kai","text":"Nhi chưa bị xóa."},{"kind":"echo","text":"Dòng log nói \"không bị xóa ngay\". Nó không nói còn bao lâu."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Hồ sơ đã nhận. Đến Ga Ngầm Số 3. Máy quét ở đó phân loại từng trường. Sai loại là bị giữ lại.\""}],"knowledge_summary":{"title":"Biến, phép gán và gán lại","sections":[{"heading":"Biến là một cái tên trỏ tới giá trị","body":"Biến là một cái tên gắn với một giá trị. Viết tên biến ở chỗ nào, Python dùng giá trị mà tên đó đang trỏ tới ở chỗ ấy."},{"heading":"Dấu `=` gán từ phải sang trái","body":"Câu `ten = gia_tri` tính vế phải trước, rồi gắn kết quả cho tên ở vế trái. Vế trái phải là một tên biến.\nTrong Python, `=` là phép gán, không phải phép so sánh bằng."},{"heading":"Dùng lại giá trị qua tên","body":"Gán một biến bằng tên của biến khác thì biến mới nhận cùng giá trị. Không cần gõ lại giá trị. Khi dữ liệu gốc thay đổi, các dòng dùng tên vẫn đúng.\nĐặt tên trong dấu nháy thì nó thành chuỗi, Python in đúng mấy chữ đó."},{"heading":"Code chạy từ trên xuống, gán lại thay giá trị từ dòng đó trở đi","body":"Python chạy từng dòng theo thứ tự từ trên xuống. Gán lại một biến thì biến mang giá trị mới, kể từ dòng gán lại.\nDòng nào chạy trước đó đã dùng giá trị cũ. Kết quả của dòng ấy không tự đổi theo."},{"heading":"Chép giá trị cũ trước khi gán lại","body":"Muốn giữ giá trị cũ, chép nó sang một biến khác trước dòng gán lại. Chép sau dòng đó thì biến mới chỉ nhận giá trị mới."},{"heading":"Quy tắc đặt tên","body":"Tên biến gồm chữ cái, chữ số và dấu `_`. Tên không có khoảng trắng và không bắt đầu bằng chữ số; viết sai thì Python báo `SyntaxError`.\nPython phân biệt chữ hoa và chữ thường: `diem_toan` và `Diem_toan` là hai biến khác nhau.\nNên viết kiểu snake_case: chữ thường, nối các từ bằng `_`, bỏ dấu tiếng Việt (`diem_toan` thay cho `điểm_toán`). Python chấp nhận chữ có dấu trong tên, nhưng tên không dấu dễ gõ đúng hơn."}],"mistakes":[{"code":"ma_khu = \"B-3\"\nprint(Ma_khu)","explain":"`Ma_khu` và `ma_khu` là hai tên khác nhau. Chưa có dòng nào gán cho `Ma_khu`, nên Python không tìm thấy tên này. Soát lại từng chữ hoa, chữ thường."},{"code":"so_phong = \"P101\"\nphong = \"so_phong\"\nprint(phong)","explain":"Có dấu nháy nên `\"so_phong\"` là một chuỗi, `phong` nhận đúng mấy chữ đó. Muốn lấy giá trị của biến thì viết tên không có dấu nháy: `phong = so_phong`."},{"code":"lop = \"10A\"\nthe_hs = \"Lop \" + lop\nlop = \"11B\"\nprint(the_hs)","explain":"`the_hs` nhận giá trị ở dòng 2, lúc `lop` còn giữ giá trị cũ. Gán lại ở dòng 3 không làm dòng 2 chạy lại. Muốn dùng giá trị mới thì đặt dòng gán lại trước dòng dùng nó."},{"code":"gio = \"8:00\"\ngio = \"9:30\"\ngio_cu = gio\nprint(gio_cu)","explain":"Dòng chép chạy sau dòng gán lại, nên `gio_cu` nhận giá trị mới. Giá trị cũ chỉ giữ được nếu chép trước khi gán lại."},{"code":"\"K-07\" = ma_khu","explain":"Vế trái của `=` phải là tên biến. Một chuỗi không nhận giá trị được. Đặt tên biến bên trái, giá trị bên phải."}],"next":"Mỗi giá trị đều có một kiểu. Bạn sẽ gặp bốn kiểu dữ liệu cơ bản của Python và cách hỏi Python xem một giá trị thuộc kiểu nào."}}', '2026-10-28T00:00:00.000Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:1.2' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:1.3', 1, '{"location":"Ga Ngầm Số 3","briefing":"[NHẬT KÝ HỆ THỐNG – GA NGẦM SỐ 3]\nSân ga bỏ hoang. Máy quét phân loại của OMNI vẫn chạy. Bốn làn màu. Mỗi trường trong hồ sơ phải rơi đúng làn của nó.\nMáy quét không đọc nội dung. Nó chỉ đọc loại của từng trường. Sai loại là bị giữ lại.\nHồ sơ ĐỖ MINH AN chép tay từ bản tin của 0xA7. Gửi thử một lần trước khi mang qua thật.\nMỗi lượt gửi, máy quét cấp một mã phiên. Hồ sơ phải khai kèm khuôn của mã phiên đó.","task_steps":["Mỗi trường hồ sơ có một làn riêng, ghi ở ô Mục tiêu: chuỗi, số nguyên, số thực hoặc đúng/sai. Viết lại giá trị từng trường cho hình dạng khớp với làn đó. Giữ nguyên nội dung hồ sơ.","`khuon_phien` phải là hình dạng của `ma_phien`, không phải con số bên trong. Đừng đoán: hỏi Python bằng `type()`.","Không sửa dòng 2: mã phiên do máy quét cấp. Bấm CHẠY. Xong khi cả 5 trường vào đúng làn và ô Mục tiêu chuyển xanh."],"objectives":[{"var":"ho_ten","label":"Họ tên"},{"var":"tuoi","label":"Tuổi"},{"var":"chieu_cao","label":"Chiều cao (mét)"},{"var":"da_tiem","label":"Đã tiêm chủng (có hay không)"},{"var":"khuon_phien","label":"Khuôn phiên: hình dạng của mã phiên"}],"hints":["Hình dạng của một giá trị nằm ngay ở cách viết ra nó. Máy quét chỉ đọc cách viết… không đọc ý nghĩa.","Lần lượt từng trường: hỏi hình dạng hiện giờ của nó, so với làn máy quét đòi, rồi viết lại giá trị theo cách viết của làn đó. Khuôn phiên thì không chép tay được. Nó là hình dạng của mã phiên… mỗi lượt phải hỏi lại.","Mảnh tài liệu Python còn đọc được:\ntype(42)      → <class ''int''>    số nguyên: chỉ có chữ số\ntype(3.5)     → <class ''float''>  số thực: phần thập phân sau dấu chấm\ntype(\"42\")    → <class ''str''>    chuỗi: nằm giữa hai dấu nháy\ntype(False)   → <class ''bool''>   chỉ có True hoặc False, viết hoa chữ đầu, không nháy\nx = 2, 5      → x là (2, 5): hai giá trị ghép lại, không phải hai rưỡi\nk = type(x)   → k giữ chính hình dạng của x lúc dòng này chạy\nprint(k)      → <class ''tuple''>"],"reactions":{"entry":"Ga Ngầm Số 3. Máy quét chia hồ sơ vào bốn làn màu. Nó không đọc nội dung… chỉ đọc hình dạng.","type_mismatch":"Máy quét giữ lại {vars}. Sai làn. Nó xếp làn theo hình dạng… ý nghĩa không tính.","type_mismatch_value_match":"Nội dung của {vars} khớp. Hình dạng thì không. In ra trông giống nhau… với máy quét, đó là hai vật khác nhau.","type_mismatch_unknown_shape":"{vars} không mang hình dạng nào trong bốn làn. Máy quét không có chỗ cho nó. Nhìn lại từng ký tự trên dòng đó… một ký tự có thể đổi cả hình dạng.","wrong_value":"Hình dạng đúng. Nội dung sai. {vars} vào đúng làn nhưng không khớp hồ sơ.","missing_var":"Sau khi chạy, bộ nhớ không có {vars}. Khe đó trống.","SyntaxError":"Dòng {line}. Trình dịch không hiểu cách viết này. Chưa câu lệnh nào chạy.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng… là ngữ pháp.","TypeError":"Dòng {line}. TypeError. Hai giá trị khác hình dạng vừa bị ép chung một phép toán.","ValueError":"Dòng {line}. ValueError. Nội dung bên trong không mang được hình dạng đó.","NameError":"Dòng {line}. NameError. Python không biết cái tên này. Với nó, mỗi ký tự đều tính.","ZeroDivisionError":"Dòng {line}. Chia cho không. Lõi từ chối.","AttributeError":"Dòng {line}. AttributeError. Giá trị này không mang thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi OMNI lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Dưới sân ga này, ta chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Mã phiên đã nằm sẵn trong bộ đệm.","system_exit":"Chương trình tự dừng giữa chừng. Máy quét không nhận được gì.","alert_exceeded":"Mọi trường vào đúng làn. Nhưng {count} câu lệnh… mỗi lần hỏi là một lần OMNI nghe thấy. Gọn hơn.","counter_ValueError":"OMNI cấp lại mã phiên. Dòng {line} vỡ: ValueError. Mã phiên mới mang hình dạng bạn chưa lường.","counter_error":"OMNI cấp lại mã phiên. Dòng {line}: {error_type}. Mã không chịu được hình dạng mới.","counter_type_mismatch":"Mã phiên mới đi qua mã của bạn… và {vars} ra sai hình dạng.","wrong_value_counter":"OMNI cấp lại mã phiên. Hình dạng đã đổi. Khuôn của bạn đứng yên… khắc cho mã phiên cũ.","counter_timeout":"OMNI cấp lại mã phiên. Mã của bạn treo… Tôi cắt kết nối. Rào chỉ mở một nửa.","two_stars":"Mọi trường vào đúng làn. Không để lại dấu vết.","three_stars":"Máy quét chuyển xanh. OMNI đổi hình dạng mã phiên, khuôn của bạn đổi theo. …Tôi ghi nhận điều đó.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại kết quả máy quét."},"reaction_variants":{"type_mismatch":"{vars} vẫn rơi xuống thùng giữ lại. Nhìn cách giá trị viết ra… máy quét xếp làn theo đúng cách viết đó.","wrong_value":"{vars} đúng làn mà vẫn sai hồ sơ. So từng ký tự với thứ máy quét chờ."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐÃ CẤP LẠI MÃ PHIÊN","outro":"Máy quét chuyển xanh. Trong nhật ký hiệu chỉnh của nó, giữa hàng nghìn dòng số, có một dòng chữ:","lore_fragment":"KTS-07: Tôi kiểm thử nó ba năm. Mười bốn nghìn lần chạy. Không một lỗi. Nó không hỏng. Tôi ước gì nó hỏng.","component":"Khuôn kiểu","outro_beats":[{"kind":"log","text":"Sau máy quét, ở cuối sân ga, có một người nằm úp mặt. Áo của người đưa tin Mạng Mù. Không còn thở."},{"kind":"echo","text":"Chip của người đó vẫn phát. Rất yếu."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Người đó không cần chip nữa. Bạn thì cần. Mang nó đến Cổng phía Bắc.\""},{"kind":"kai","text":"Làm sao nó biết có xác người ở đây?"},{"kind":"echo","text":"Dữ liệu trong chip… toàn là ký tự."}],"knowledge_summary":{"title":"Bốn kiểu cơ bản và hàm type()","sections":[{"heading":"Bốn kiểu cơ bản","body":"Mỗi giá trị trong Python có một kiểu. Kiểu đến từ cách bạn viết giá trị ra:\nChữ nằm giữa hai dấu nháy, như `\"...\"`, là `str` (chuỗi).\nSố nguyên, không có phần thập phân, là `int`.\nSố có dấu chấm thập phân là `float` (số thực).\n`True` và `False`, viết hoa chữ đầu và không có nháy, là `bool` (giá trị đúng/sai)."},{"heading":"`type()` cho biết kiểu của một giá trị","body":"`type(x)` trả về kiểu của `x`. In kết quả ra sẽ thấy dạng `<class ''int''>`, trong đó chữ giữa hai dấu nháy là tên kiểu.\nChỉ nhìn giá trị in ra thì chưa biết được kiểu: `print` in `42` và `\"42\"` giống hệt nhau. Muốn chắc, hãy hỏi `type()`."},{"heading":"Kiểu cũng là một giá trị","body":"`type()` trả về chính kiểu đó, không phải đoạn chữ mô tả nó. Bạn gán được kết quả cho biến và so sánh được với `int`, `str`.\n`type()` đọc giá trị ngay lúc dòng lệnh chạy. Đầu vào đổi kiểu thì kết quả đổi theo. Một tên kiểu chép tay vào code thì đứng yên."},{"heading":"Số thập phân dùng dấu chấm","body":"Python viết số thập phân bằng dấu chấm: `2.5`. Dấu phẩy với Python là dấu ngăn cách. `b = 2, 5` tạo một tuple (nhiều giá trị ghép thành một nhóm) gồm hai số `2` và `5`.\nPython không báo lỗi ở dòng này, nên rất dễ bỏ sót."},{"heading":"Có nháy và không có nháy","body":"Dấu nháy biến mọi thứ bên trong thành chuỗi. `\"15\"` là chuỗi gồm hai ký tự, còn `15` là số nguyên. `\"False\"` là chuỗi năm ký tự, còn `False` là giá trị đúng/sai.\nChuỗi và số không bao giờ bằng nhau, dù in ra trông giống nhau."}],"mistakes":[{"code":"can_nang = 52,5","explain":"Dấu phẩy ghép hai số thành một tuple. Số thập phân viết bằng dấu chấm: `52.5`."},{"code":"co_mat = true","explain":"Python phân biệt chữ hoa và chữ thường. Hai giá trị đúng/sai viết là `True` và `False`. Viết `true` thì Python hiểu đó là tên một biến chưa có."},{"code":"co_mat = \"True\"","explain":"Có dấu nháy thì là chuỗi, dù chữ bên trong là True. Bỏ dấu nháy để có giá trị kiểu `bool`."},{"code":"so_phong = 05","explain":"Python không cho số nguyên bắt đầu bằng số 0. Viết `5`. Nếu cần giữ số 0 ở đầu, như một mã số, thì dùng chuỗi `\"05\"`."},{"code":"kieu = \"int\"","explain":"`\"int\"` là chuỗi ba ký tự, không phải kiểu. Kiểu viết không có nháy: `int`. Khi kiểu phụ thuộc vào một giá trị khác, dùng `type(gia_tri)` để Python tự trả lời."}],"next":"Dữ liệu sẽ đến dưới dạng chuỗi, như `\"16\"` hay `\"7.5\"`. Bạn sẽ chuyển chuỗi sang số bằng `int()` và `float()`, rồi tính toán với kết quả."}}', '2026-10-28T00:00:00.000Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:1.3' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:1.4', 1, '{"location":"Cổng phía Bắc","briefing":"[NHẬT KÝ HỆ THỐNG – CỔNG PHÍA BẮC]\nChip Neural-ID thu hồi từ một người đã chết. Dữ liệu còn đọc được… nhưng toàn là chuỗi ký tự.\nMáy quét chỉ nhận số. Đưa chuỗi vào là báo động.","task_steps":["Dữ liệu chip trong `tuoi`, `chieu_cao` và `cap_do` là chuỗi, kể cả khi trông như số. Không sửa 3 dòng khóa đó.","Sửa các dòng tính cho mỗi biến ra đúng kiểu ở ô Mục tiêu: `ma_xac_thuc` là `int`, `chi_so` là `float` làm tròn 2 chữ số thập phân, `hop_le` là `bool` chứ không phải chữ.","Đừng gõ tay kết quả. Sau lượt chạy đầu, OMNI đổi dữ liệu chip, và mã phải tính đúng cả với dữ liệu mới.","Bấm CHẠY. Xong khi cả 3 mục tiêu chuyển xanh. Dùng không quá 8 câu lệnh và qua được lượt OMNI đổi dữ liệu thì được thêm sao."],"objectives":[{"var":"ma_xac_thuc","label":"Mã xác thực = tuổi × 100 + cấp độ"},{"var":"chi_so","label":"Chỉ số sinh học = chiều cao × 2, làm tròn 2 chữ số thập phân"},{"var":"hop_le","label":"Cờ hợp lệ: giá trị đúng/sai, không phải chữ"}],"hints":["Nhìn mô phỏng sau khi chạy. Dữ liệu chip là chữ, kể cả khi trông như số. Nhân chữ với 100 không ra phép tính… Python chép chữ đó nối đuôi nhau 100 lần.","Python có sẵn công cụ đổi hình dạng. Mỗi công cụ mang đúng tên hình dạng nó tạo ra, cũng là tên làn máy quét đòi. Đổi dữ liệu chip trước, rồi mới tính. Chip có thể ghi số kèm phần thập phân… nên thứ tự đổi cũng quan trọng.","Mảnh tài liệu Python còn đọc được:\nint(\"42\")        → 42\nint(7.9)         → 7      (cắt bỏ phần thập phân)\nfloat(\"2.5\")     → 2.5\nfloat(3)         → 3.0\nround(2.71828, 3) → 2.718\nMỗi hàm nhận một giá trị và trả về giá trị mới mang hình dạng khác. Giá trị gốc không đổi."],"reactions":{"entry":"Cổng phía Bắc. Chip của người đưa tin vẫn phát. Máy quét phía trước chỉ nhận số.","type_mismatch":"Máy quét từ chối {vars}. Sai hình dạng. Nó không đọc nội dung… chỉ đọc hình dạng.","type_mismatch_value_match":"Con số của {vars} khớp. Hình dạng thì không. Với máy quét, đó vẫn là vật lạ.","wrong_value":"Hình dạng đúng. Con số sai. {vars} không khớp mẫu máy quét đang chờ.","missing_var":"Sau khi chạy, bộ nhớ không có {vars}. Máy quét không có gì để đọc.","SyntaxError":"Dòng {line}. Trình dịch không hiểu cấu trúc này. Chưa câu lệnh nào chạy.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng… là ngữ pháp.","TypeError":"Dòng {line}. TypeError. Hai thứ khác hình dạng vừa bị ép vào cùng một phép toán.","ValueError":"Dòng {line}. ValueError. Nội dung bên trong không chuyển được sang hình dạng đó.","NameError":"Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự.","ZeroDivisionError":"Dòng {line}. Chia cho không. Lõi từ chối.","AttributeError":"Dòng {line}. AttributeError. Dữ liệu này không mang thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi OMNI lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở Vùng Tối, ta chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Dữ liệu đã nằm sẵn trong chip.","system_exit":"Chương trình tự dừng giữa chừng. Máy quét không nhận được gì.","alert_exceeded":"Qua máy quét. Nhưng {count} câu lệnh… Sentinel đã ghi nhận tín hiệu. Chạy gọn hơn.","counter_ValueError":"OMNI đổi định dạng chip. Dòng {line} vỡ: ValueError. Dữ liệu mới mang hình dạng bạn chưa lường.","counter_error":"OMNI đổi dữ liệu. Dòng {line}: {error_type}. Mã không trụ nổi.","counter_type_mismatch":"Dữ liệu mới đi qua mã của bạn… và ra sai hình dạng ở {vars}.","wrong_value_counter":"OMNI đổi dữ liệu chip. Kết quả của bạn không đổi theo. Nó viết cho một con chip đã chết.","counter_timeout":"OMNI đổi dữ liệu chip. Mã của bạn treo trên dữ liệu mới… Tôi cắt kết nối. Cổng chỉ mở một nửa.","two_stars":"Qua cổng. Không để lại dấu vết.","three_stars":"Cổng mở hoàn toàn. OMNI đổi dữ liệu, mã vẫn đứng vững. …Tôi ghi nhận điều đó.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại kết quả máy quét.","string_repeated":"Nhìn chữ số trong mô phỏng. Chúng bị chép nối đuôi nhau. Nhân chữ với một con số không ra phép tính… chỉ lặp chữ đó từng ấy lần."},"reaction_variants":{"type_mismatch":"{vars} vẫn sai hình dạng. Con số trông ra sao, máy quét mặc kệ… nó chỉ đọc hình dạng.","string_repeated":"Dữ liệu chip vẫn là chữ khi phép nhân chạy. Chữ nhân lên thì dài ra… không lớn lên.","ValueError":"Dòng {line}. Vẫn ValueError. Đọc phần cuối thông báo lỗi. Đó là thứ Python đang cố đổi hình dạng."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐÃ THAY ĐỔI ĐỊNH DẠNG CHIP","outro":"Cổng phía Bắc mở. Trong bộ nhớ chip còn sót một dòng log chưa bị xóa:","lore_fragment":"KTS-03: Nếu ai đọc được dòng này, mảnh đầu tiên nằm dưới Cổng Kiểm Soát. Đừng tin tín hiệu nào mang mã 0xA7.","component":"Dữ liệu sinh trắc","outro_beats":[{"kind":"kai","text":"0xA7. Người đã dẫn tôi tới cái xác này."},{"kind":"echo","text":"Tôi đã đọc lại mọi gói 0xA7 gửi. Không gói nào đi qua trạm chuyển tiếp nào của Mạng Mù."},{"kind":"kai","text":"Vậy nó đến từ đâu?"},{"kind":"echo","text":"Từ một tầng mạng mà Vùng Tối không có."}],"knowledge_summary":{"title":"Đổi kiểu dữ liệu: int(), float(), str(), round()","sections":[{"heading":"Chuỗi trông như số vẫn là chuỗi","body":"Giá trị trong dấu nháy là chuỗi (`str`), kể cả khi chỉ gồm chữ số. Với chuỗi, `*` lặp chuỗi đó nhiều lần, còn `+` nối hai chuỗi lại.\nPython không báo lỗi ở đây. Chương trình vẫn chạy, chỉ có kết quả là sai."},{"heading":"`int()` và `float()` đổi chuỗi thành số","body":"`int(x)` trả về số nguyên, `float(x)` trả về số thực. Đổi kiểu trước, tính sau. Khi đó `*` và `+` làm phép toán trên số."},{"heading":"Chuỗi có phần thập phân: đổi qua `float()` trước","body":"`int()` chỉ đọc được chuỗi viết như số nguyên. Gặp chuỗi như `\"8.0\"`, nó báo `ValueError`. Cách làm là đổi sang `float` trước, rồi mới đổi sang `int`.\nKhi nhận một số thực, `int()` cắt bỏ phần thập phân chứ không làm tròn."},{"heading":"`round(x, n)` làm tròn","body":"`round(x, n)` trả về `x` làm tròn tới `n` chữ số sau dấu chấm. Không có `n` thì kết quả là số nguyên.\nMáy tính lưu số thực ở hệ nhị phân nên phép tính có thể lệch rất nhỏ, như `0.1 + 0.2` dưới đây; `round()` đưa kết quả về đúng số chữ số bạn cần."},{"heading":"Hàm đổi kiểu không sửa giá trị gốc","body":"`int(x)` tạo ra một giá trị mới, còn `x` vẫn là chuỗi như cũ. Muốn dùng kết quả thì gán nó cho một biến."},{"heading":"`str()` và kiểu `bool`","body":"`str(x)` đổi một giá trị thành chuỗi, cần khi muốn nối số vào chữ bằng `+`.\n`True` và `False` là hai giá trị kiểu `bool`, viết không có dấu nháy. Viết trong dấu nháy thì đó là chuỗi."}],"mistakes":[{"code":"ma_xac_thuc = tuoi * 100 + cap_do","explain":"`tuoi` và `cap_do` là chuỗi, nên `*` lặp chuỗi `\"27\"` 100 lần rồi `+` nối thêm `\"3\"` vào cuối. Đổi cả hai sang số trước khi tính."},{"code":"ma_xac_thuc = int(tuoi) * 100 + cap_do","explain":"Mới đổi `tuoi`, còn `cap_do` vẫn là chuỗi. Python không cộng số với chuỗi. Phải đổi mọi giá trị trong phép tính sang số."},{"code":"int(\"31.0\")","explain":"`int()` không đọc được chuỗi có dấu chấm. Dùng `int(float(\"31.0\"))`: `float()` đọc chuỗi trước, `int()` lấy phần nguyên sau."},{"code":"hop_le = \"True\"","explain":"Dấu nháy biến `True` thành chuỗi bốn ký tự. Viết `True` không có dấu nháy."},{"code":"chi_so = float(chieu_cao) * 2","explain":"Với `\"1.72\"`, kết quả 3.44 tình cờ đã tròn nên lỗi không lộ ra. Dữ liệu khác thì lộ. Bọc phép tính trong `round(..., 2)`."}],"next":"Bạn sẽ dùng các toán tử số học `+`, `-`, `*`, `/`, `//`, `%`, `**` trên những con số vừa đổi kiểu."}}', '2026-10-28T00:00:00.000Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:1.4' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
